# Generated by wickfleet from a strategy spec (v1). Change the spec, not this file.
# Demo: long when EMA 12 crosses above EMA 26 while price is above SMA 200, out when EMA 12 crosses back below.
import talib.abstract as ta
from freqtrade.strategy import IStrategy
from pandas import DataFrame


class EmaCross(IStrategy):
    INTERFACE_VERSION = 3
    timeframe = "1d"
    minimal_roi = {"0": 100}
    stoploss = -0.15
    startup_candle_count = 200

    def populate_indicators(self, df: DataFrame, metadata: dict) -> DataFrame:
        df["ema12"] = ta.EMA(df, timeperiod=12, price="close")
        df["ema26"] = ta.EMA(df, timeperiod=26, price="close")
        df["sma200"] = df["close"].rolling(200).mean()
        return df

    def populate_entry_trend(self, df: DataFrame, metadata: dict) -> DataFrame:
        df.loc[((df["ema12"] > df["ema26"]) & (df["ema12"].shift(1) <= df["ema26"].shift(1))) & (df["close"] > df["sma200"]), "enter_long"] = 1
        return df

    def populate_exit_trend(self, df: DataFrame, metadata: dict) -> DataFrame:
        df.loc[((df["ema12"] < df["ema26"]) & (df["ema12"].shift(1) >= df["ema26"].shift(1))), "exit_long"] = 1
        return df
